import os
from pathlib import Path

SUBDIRS = ("jobs", "state", "locks")


def resolve() -> Path:
    """APP_DATA, or ~/.local/share/app when unset or empty."""
    return Path(os.environ.get("APP_DATA") or Path.home() / ".local/share/app")


def ensure_dirs(root: Path) -> None:
    for d in SUBDIRS:
        (root / d).mkdir(mode=0o700, parents=True, exist_ok=True)
